# Pure formula arithmetic; hydration is part of the explicitly given school model.
AW=dict(H=1,C=12,O=16,Si=28,Na=23,N=14,Mg=24,Al=27,S=32,Cl=35.5,K=39,Ca=40,Fe=56,Cu=63.5,Zn=65,Ag=108,Sn=119,Pb=207,Hg=200,Cr=52,Ni=59,Au=197)
def atoms(formula):
 s=formula.translate(str.maketrans('₀₁₂₃₄₅₆₇₈₉','0123456789'));total={}
 for component in s.split('·'):
  m=re.match(r'^(\d+)?(.*)$',component);mult=int(m[1] or 1);tokens=re.findall(r'[A-Z][a-z]?|\d+|[()]',m[2]);stack=[{}];i=0
  while i<len(tokens):
   tok=tokens[i];i+=1
   if tok=='(':stack.append({});continue
   group=stack.pop()if tok==')'else{tok:1};n=1
   if i<len(tokens)and tokens[i].isdigit():n=int(tokens[i]);i+=1
   for e,k in group.items():stack[-1][e]=stack[-1].get(e,0)+k*n
  assert len(stack)==1
  for e,k in stack[0].items():total[e]=total.get(e,0)+k*mult
 return total
def molar(f):return sum(AW[e]*n for e,n in atoms(f).items())
