def render_text(s):
 s=html.escape(s)
 def image(m):
  path=R/'public/question-bank'/m[2];data=base64.b64encode(path.read_bytes()).decode();return f'<img alt="{m[1]}" src="data:image/png;base64,{data}">'
 return re.sub(r'!\[([^\]]*)\]\(https://proshnobook.com/question-bank/([^)]*)\)',image,s).replace('\n','<br>')
